const lessons=[{"sentences":[{"speaker":"A","text":"Good morning and welcome to the central sports facility how can I help you today.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.043666666666667},{"speaker":"B","text":"Good morning I would like to ask about the membership plans and evening classes.","position":2,"audioStartSeconds":5.243666666666667,"audioEndSeconds":10.028041666666667},{"speaker":"A","text":"We offer several options but our most popular choice is the annual membership.","position":3,"audioStartSeconds":10.228041666666666,"audioEndSeconds":15.087041666666666},{"speaker":"B","text":"That sounds interesting although I need to know the monthly cost before deciding.","position":4,"audioStartSeconds":15.287041666666667,"audioEndSeconds":20.081625},{"speaker":"A","text":"The monthly fee for the standard individual package is exactly forty five pounds.","position":5,"audioStartSeconds":20.281625,"audioEndSeconds":25.66825},{"speaker":"B","text":"That fits my budget quite well because I expected a higher price.","position":6,"audioStartSeconds":25.86825,"audioEndSeconds":30.327041666666666},{"speaker":"A","text":"You also receive full access to the swimming pool if you join before Friday.","position":7,"audioStartSeconds":30.527041666666666,"audioEndSeconds":35.38529166666667},{"speaker":"B","text":"Wonderful and which yoga class is scheduled for Tuesday evenings.","position":8,"audioStartSeconds":35.58529166666667,"audioEndSeconds":40.044041666666665},{"speaker":"A","text":"We have a gentle flow session which starts at six thirty pm.","position":9,"audioStartSeconds":40.24404166666667,"audioEndSeconds":44.53525},{"speaker":"B","text":"Actually I prefer a more intense workout when I visit the gym.","position":10,"audioStartSeconds":44.73525,"audioEndSeconds":49.039375},{"speaker":"A","text":"In that case you should choose the power yoga class on Thursday nights.","position":11,"audioStartSeconds":49.239375,"audioEndSeconds":53.6595},{"speaker":"B","text":"Thursday night sounds perfect since my schedule is completely free then.","position":12,"audioStartSeconds":53.8595,"audioEndSeconds":58.66620833333333},{"speaker":"A","text":"Let me note down your chosen class for Thursday evening right now.","position":13,"audioStartSeconds":58.86620833333333,"audioEndSeconds":63.093},{"speaker":"B","text":"Please also record my preferred contact method as email for updates.","position":14,"audioStartSeconds":63.293,"audioEndSeconds":68.177},{"speaker":"A","text":"I have updated your profile with your email address for all future messages.","position":15,"audioStartSeconds":68.377,"audioEndSeconds":73.3415},{"speaker":"B","text":"Thank you for your helpful assistance with my sports centre registration today.","position":16,"audioStartSeconds":73.5415,"audioEndSeconds":78.367625}],"questions":[{"prompt":"Most popular choice: ______ membership","answer":"annual","evidenceSentence":3,"evidence":"annual membership","explanation":"Người nói A cho biết lựa chọn phổ biến nhất là 'annual' membership."},{"prompt":"Monthly fee: ______ pounds","answer":"forty five","evidenceSentence":5,"evidence":"forty five pounds","explanation":"Chi phí hàng tháng là 'forty five' pounds."},{"prompt":"Extra pool access deadline day: ______","answer":"Friday","evidenceSentence":7,"evidence":"before Friday","explanation":"Khách hàng nhận được quyền sử dụng hồ bơi miễn là đăng ký trước ngày 'Friday'."},{"prompt":"Tuesday evening yoga class type: ______ flow","answer":"gentle","evidenceSentence":9,"evidence":"gentle flow","explanation":"Lớp yoga tối thứ Ba là 'gentle' flow."},{"prompt":"Chosen workout class night: ______","answer":"Thursday","evidenceSentence":11,"evidence":"Thursday nights","explanation":"Khách hàng chọn lớp yoga mạnh vào các tối thứ 'Thursday'."},{"prompt":"Preferred contact method: ______","answer":"email","evidenceSentence":14,"evidence":"as email","explanation":"Phương thức liên lạc ưu tiên được ghi nhận là 'email'."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
